Let me think about this differently. The MSAN crash is in `bn_trim` reading `a->dp[a->used - 1]`. This means `a->used` is set to a value such that `a->dp[a->used - 1]` was never initialized.

Looking at `bn_add_imp` again:
```c
static void bn_add_imp(bn_t c, const bn_t a, const bn_t b) {
        int max, min;
        dig_t carry;

        max = a->used;
        min = b->used;

        /* Grow the result. */
        bn_grow(c, max);

        if (min == 0) {
                bn_copy(c, a);
                return;
        }

        if (a->used == b->used) {
                carry = bn_addn_low(c->dp, a->dp, b->dp, max);
        } else {
                carry = bn_addn_low(c->dp, a->dp, b->dp, min);
                carry = bn_add1_low(c->dp + min, a->dp + min, carry, max - min);
        }
        if (carry) {
                bn_grow(c, max + 1);
                c->dp[max] = carry;
        }
        c->used = max + carry;
        bn_trim(c);
}
```

